#include <iostream>
#include <fstream>
class FileHandler {
public:
  FileHandler(const std::string& filename) : file_(filename) {
    if (!file_.is_open()) {
      throw std::runtime_error("Could not open file");
    }
  }
  ~FileHandler() {
    if (file_.is_open()) {
      file_.close();
    }
  }
  std::ofstream& get_file() { return file_; }
private:
  std::ofstream file_;
};
int main() {
  try {
    FileHandler file("mydata.txt");
    file.get_file() << "Hello, RAII!\n";
  } catch (const std::runtime_error& error) {
    std::cerr << "Error: " << error.what() << std::endl;
  }
  return 0;
}
